+        QueryBuilder rewrittenQuery = parser.parseKqlQuery(query, createKqlParserContext(context));
+
+        log.trace(() -> Strings.format("KQL query %s translated to Query DSL: %s", query, Strings.toString(rewrittenQuery)));
