+                        subQuery = String.valueOf(randomDouble());
+                    }
+                    subQuery = randomBoolean() ? '"' + subQuery + '"' : subQuery;
+                }
+
+                subQuery = fieldName + operator + subQuery;
+            }
+
+            if (randomBoolean() && subQuery.isEmpty() == false) {
+                subQuery = '(' + subQuery + ')';
+            }
+
+            if (randomBoolean()) {
+                subQuery = "NOT " + subQuery;
+            }
+
+            if (randomBoolean() && subQuery.isEmpty() == false) {
+                subQuery = '(' + subQuery + ')';
+            }
+
+            return subQuery;
